  spr jsonb := '["Sprints", "Hurdles", "Long Jump", "High Jump", "Pole Vault"]'::jsonb;
  cur jsonb; p jsonb; dd jsonb; keep jsonb;
  fw int; fd int; n int := 0; miss int := 0;
begin
  select value into cur from public.hub_data where key = 'workouts' for update;
  if cur is null or jsonb_typeof(cur) <> 'array' then raise exception 'No posted workouts found. Run the plan files first.'; end if;
  for p in select * from jsonb_array_elements(patches) loop
    fw := null; fd := null;
    for i in 0 .. jsonb_array_length(cur) - 1 loop
      if cur -> i ->> 'start' = p ->> 'start' then fw := i; end if;
    end loop;
    if fw is not null then
      for j in 0 .. jsonb_array_length(coalesce(cur -> fw -> 'days', '[]'::jsonb)) - 1 loop
        if cur -> fw -> 'days' -> j ->> 'day' = p ->> 'day' then fd := j; end if;
      end loop;
    end if;
    if fd is null then
      miss := miss + 1;
      raise notice 'Skipped % %: that day is not posted yet', p ->> 'start', p ->> 'day';
      continue;
    end if;
    dd := cur -> fw -> 'days' -> fd;
    select coalesce(jsonb_agg(c), '[]'::jsonb) into keep
      from jsonb_array_elements(case when jsonb_typeof(dd -> 'combos') = 'array' then dd -> 'combos' else '[]'::jsonb end) c
      where c -> 'groups' <> spr;
    dd := jsonb_set(dd, '{combos}', keep || jsonb_build_array(jsonb_build_object('groups', spr, 'items', p -> 'items')));
    dd := jsonb_set(dd, '{gfocus}', coalesce(nullif(dd -> 'gfocus', 'null'::jsonb), '{}'::jsonb) || (p -> 'gfocus'));
    cur := jsonb_set(cur, array[fw::text, 'days', fd::text], dd);
    n := n + 1;
  end loop;
  insert into public.hub_data (key, value, updated_at) values ('workouts', cur, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  raise notice 'Spring sprint plan posted: % of % days updated (% skipped).', n, jsonb_array_length(patches), miss;
end
$do$;
